#ifndef THIRD_PARTY_BLINK_RENDERER_PLATFORM_GRAPHICS_DOM_NODE_ID_TRAITS_H_
#define THIRD_PARTY_BLINK_RENDERER_PLATFORM_GRAPHICS_DOM_NODE_ID_TRAITS_H_

#include <stdint.h>

#include <type_traits>

#include "third_party/blink/public/common/dom/dom_node_id.h"
#include "third_party/blink/renderer/platform/wtf/hash_functions.h"
#include "third_party/blink/renderer/platform/wtf/hash_traits.h"

namespace blink {

template <>
struct HashTraits<DOMNodeIdType> : GenericHashTraits<DOMNodeIdType> {
  static uint32_t GetHash(const DOMNodeIdType& id) {
    return HashInt(id.value());
  }

  // Match integer-key sentinels to preserve the full positive ID range
  // generated by `DOMNodeIds`, including INT32_MAX.
  static constexpr bool kEmptyValueIsZero = true;
  static constexpr DOMNodeIdType EmptyValue() { return DOMNodeIdType(); }
  static constexpr DOMNodeIdType DeletedValue() { return DOMNodeIdType(-1); }

  // Preserve integer-key GC policies during migration. `GenericHashTraits`
  // would disable compaction and forbid GC during moves, even though this
  // wrapper is trivially copyable and movable.
  static_assert(std::is_trivially_copyable_v<DOMNodeIdType>);
  static_assert(std::is_trivially_move_constructible_v<DOMNodeIdType>);
  static constexpr bool kSupportsCompaction = true;
  template <typename U = void>
  struct NeedsToForbidGCOnMove {
    static constexpr bool value = false;
  };
};

}  // namespace blink

#endif  // THIRD_PARTY_BLINK_RENDERER_PLATFORM_GRAPHICS_DOM_NODE_ID_TRAITS_H_
